canvas.addEventListener('mousemove', e => {
  if (!canvas.isDragging) return;
  const dx = e.offsetX - canvas.dragStart.x;
  const dy = e.offsetY - canvas.dragStart.y;
  ship.vx += dx * 0.01;
  ship.vy += dy * 0.01;
  canvas.dragStart = {x:e.offsetX, y:e.offsetY};
});

