  if (keys['ArrowUp'] || keys['w']) { ship.vy -= ship.thrust; playTone(400, 0.05); }
  if (keys['ArrowDown'] || keys['s']) { ship.vy += ship.thrust; }
  if (keys['ArrowLeft'] || keys['a']) { ship.vx -= ship.thrust; }

